CREATE TABLE public.outlook_deadline_settings (id boolean PRIMARY KEY DEFAULT true CHECK(id), enabled boolean NOT NULL DEFAULT false, updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON public.outlook_deadline_settings FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.outlook_deadline_settings TO authenticated;
GRANT SELECT,INSERT,UPDATE ON public.outlook_deadline_settings TO service_role;
ALTER TABLE public.outlook_deadline_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY deadline_settings_admin ON public.outlook_deadline_settings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.outlook_deadline_outbox (task_id uuid PRIMARY KEY REFERENCES public.internal_tasks(id),revision bigint NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','blocked','inflight','synced','removed','conflict','uncertain','failed')),event_id text,account_id text,calendar_id text,etag text,transaction_id uuid NOT NULL DEFAULT gen_random_uuid(),lock_token uuid,lock_until timestamptz,claimed_revision bigint,last_error text,applied jsonb,history jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),CHECK(event_id IS NULL OR (account_id IS NOT NULL AND calendar_id IS NOT NULL AND etag IS NOT NULL)));
REVOKE ALL ON public.outlook_deadline_outbox FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.outlook_deadline_outbox TO authenticated;
GRANT SELECT,INSERT,UPDATE ON public.outlook_deadline_outbox TO service_role;
ALTER TABLE public.outlook_deadline_outbox ENABLE ROW LEVEL SECURITY;
CREATE POLICY deadline_outbox_admin ON public.outlook_deadline_outbox FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.outlook_deadline_admin() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Alleen beheerders' USING ERRCODE='42501'; END IF; END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_admin() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.outlook_deadline_configure(_enabled boolean,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce(public.has_role(_actor,'admin'),false) THEN RAISE EXCEPTION 'Alleen beheerders'; END IF; INSERT INTO public.outlook_deadline_settings(id,enabled,updated_by) VALUES(true,_enabled,_actor) ON CONFLICT(id) DO UPDATE SET enabled=EXCLUDED.enabled,updated_by=_actor,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_configure(boolean,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.outlook_deadline_configure(boolean,uuid) TO service_role;
CREATE FUNCTION public.outlook_deadline_enqueue(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.outlook_deadline_outbox WHERE task_id=_id) OR coalesce((SELECT enabled FROM public.outlook_deadline_settings WHERE id),false) THEN INSERT INTO public.outlook_deadline_outbox(task_id) VALUES(_id) ON CONFLICT(task_id) DO UPDATE SET revision=outlook_deadline_outbox.revision+1,state=CASE WHEN outlook_deadline_outbox.state IN ('inflight','uncertain','conflict') THEN outlook_deadline_outbox.state ELSE 'pending' END,updated_at=now(); END IF; END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_enqueue(uuid) FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.outlook_deadline_task_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR ROW(NEW.title,NEW.deadline,NEW.assignee_id,NEW.status,NEW.project_id) IS DISTINCT FROM ROW(OLD.title,OLD.deadline,OLD.assignee_id,OLD.status,OLD.project_id) THEN PERFORM public.outlook_deadline_enqueue(NEW.id); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_task_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_outlook_deadline_task AFTER INSERT OR UPDATE ON public.internal_tasks FOR EACH ROW EXECUTE FUNCTION public.outlook_deadline_task_changed();
CREATE FUNCTION public.outlook_deadline_project_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; BEGIN IF NEW.archived_at IS DISTINCT FROM OLD.archived_at THEN FOR t IN SELECT id FROM public.internal_tasks WHERE project_id=NEW.id LOOP PERFORM public.outlook_deadline_enqueue(t.id); END LOOP; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_project_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_outlook_deadline_project AFTER UPDATE ON public.internal_projects FOR EACH ROW EXECUTE FUNCTION public.outlook_deadline_project_changed();
CREATE FUNCTION public.outlook_deadline_mapping_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t record; BEGIN FOR t IN SELECT id FROM public.internal_tasks WHERE assignee_id=coalesce(NEW.user_id,OLD.user_id) LOOP PERFORM public.outlook_deadline_enqueue(t.id); END LOOP; RETURN coalesce(NEW,OLD); END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_mapping_changed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_outlook_deadline_mapping AFTER INSERT OR UPDATE OR DELETE ON public.planner_user_map FOR EACH ROW EXECUTE FUNCTION public.outlook_deadline_mapping_changed();
CREATE FUNCTION public.outlook_deadline_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.outlook_deadline_outbox; t public.internal_tasks; m public.planner_user_map; archived boolean; BEGIN PERFORM public.outlook_deadline_admin(); IF NOT coalesce((SELECT enabled FROM public.outlook_deadline_settings WHERE id),false) THEN RETURN NULL; END IF; UPDATE public.outlook_deadline_outbox SET state='uncertain',last_error='Verwerking onderbroken; controleer Outlook. Geen automatische heraanmaak.',lock_token=NULL,lock_until=NULL WHERE state='inflight' AND lock_until<now(); SELECT * INTO q FROM public.outlook_deadline_outbox WHERE state='pending' ORDER BY updated_at FOR UPDATE SKIP LOCKED LIMIT 1; IF NOT FOUND THEN RETURN NULL; END IF; SELECT * INTO t FROM public.internal_tasks WHERE id=q.task_id; SELECT * INTO m FROM public.planner_user_map WHERE user_id=t.assignee_id AND confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL AND public.has_role(user_id,'admin') AND entra_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'; SELECT archived_at IS NOT NULL INTO archived FROM public.internal_projects WHERE id=t.project_id; UPDATE public.outlook_deadline_outbox SET state='inflight',lock_token=gen_random_uuid(),lock_until=now()+interval '5 minutes',claimed_revision=revision WHERE task_id=q.task_id RETURNING * INTO q; RETURN to_jsonb(q)||jsonb_build_object('task',jsonb_build_object('id',t.id,'title',t.title,'deadline',t.deadline,'assignee_id',t.assignee_id,'project_id',t.project_id,'status',t.status,'archived',coalesce(archived,false)),'mapped_account',m.entra_id); END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_claim() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.outlook_deadline_claim() TO authenticated;
CREATE FUNCTION public.outlook_deadline_valid(_task uuid,_lock uuid,_revision bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.outlook_deadline_admin(); RETURN coalesce((SELECT enabled FROM public.outlook_deadline_settings WHERE id),false) AND EXISTS(SELECT 1 FROM public.outlook_deadline_outbox WHERE task_id=_task AND lock_token=_lock AND lock_until>now() AND revision=_revision AND state='inflight'); END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_valid(uuid,uuid,bigint) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.outlook_deadline_valid(uuid,uuid,bigint) TO authenticated;
CREATE FUNCTION public.outlook_deadline_finish(_task uuid,_lock uuid,_result jsonb,_actor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q public.outlook_deadline_outbox; s text; BEGIN IF NOT coalesce(public.has_role(_actor,'admin'),false) THEN RAISE EXCEPTION 'Alleen beheerders'; END IF; SELECT * INTO q FROM public.outlook_deadline_outbox WHERE task_id=_task FOR UPDATE; IF q.lock_token IS DISTINCT FROM _lock OR q.state<>'inflight' OR q.lock_until<now() THEN RAISE EXCEPTION 'Slot verloren'; END IF; s:=_result->>'state'; IF s NOT IN ('pending','blocked','synced','removed','conflict','uncertain','failed') THEN RAISE EXCEPTION 'Ongeldige uitkomst'; END IF; UPDATE public.outlook_deadline_outbox SET state=CASE WHEN (revision<>claimed_revision OR (_result->>'followup')='true') AND s NOT IN ('uncertain','conflict') THEN 'pending' ELSE s END,event_id=CASE WHEN _result ? 'event_id' THEN _result->>'event_id' ELSE event_id END,account_id=CASE WHEN _result ? 'account_id' THEN _result->>'account_id' ELSE account_id END,calendar_id=CASE WHEN _result ? 'calendar_id' THEN _result->>'calendar_id' ELSE calendar_id END,etag=CASE WHEN _result ? 'etag' THEN _result->>'etag' ELSE etag END,applied=CASE WHEN _result ? 'applied' THEN _result->'applied' ELSE applied END,transaction_id=CASE WHEN s='removed' THEN gen_random_uuid() ELSE transaction_id END,history=history||jsonb_build_array(jsonb_build_object('at',now(),'actor',_actor,'event',q.event_id,'account',q.account_id,'state',s)),last_error=left(_result->>'error',500),lock_token=NULL,lock_until=NULL,updated_at=now() WHERE task_id=_task; END $$;
REVOKE ALL ON FUNCTION public.outlook_deadline_finish(uuid,uuid,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.outlook_deadline_finish(uuid,uuid,jsonb,uuid) TO service_role;